style.css:
@-moz-document domain("roblox.com") {
body {
    background: url(https://i.pinimg.com/736x/73/2b/9f/732b9f1dc5549f99fe88e875e8b4efe6.jpg) no-repeat center center fixed;
    background-size: cover;
  }

  /* Make background visible by adjusting opaque sections */
  #header, .navbar, .container-main, .content, .section-content {
    background-color: rgba(0, 0, 0, 0.6) !important;
    color: white !important;
  }

  /* Optional: Style links and buttons */
  a, .btn-primary {
    color: #ff9de2 !important;
    background-color: rgba(235, 185, 215, 0.1) !important;
    border: 1px solid #ff9de2 !important;
  }

  /* Optional: Rounded corners and font */
  * {
    border-radius: 10px !important;
    font-family: "Poppins", sans-serif !important;
  }
}
